function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length > 30000) return 's has at most 30000 characters.';
  if (!/^[()]*$/.test(s)) return "s may contain only '(' and ')'.";
  return null;
}

