function longestValidParentheses(s) {
  let best = 0;
  for (let start = 0; start < s.length; start++) {
    let balance = 0;
    for (let end = start; end < s.length; end++) {
      balance += s[end] === '(' ? 1 : -1;
      if (balance < 0) break;
      if (balance === 0) best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

