function generate(rand, size) {
  if (size === 'small') {
    const n = Math.floor(rand() * 13);
    const lean = 0.3 + rand() * 0.4;
    let s = '';
    for (let i = 0; i < n; i++) s += rand() < lean ? '(' : ')';
    return [s];
  }
  // Large: balanced blocks of varied depth separated by stray brackets, so long valid runs appear.
  const n = 6000 + Math.floor(rand() * 4000);
  let s = '';
  while (s.length < n) {
    if (rand() < 0.08) { s += rand() < 0.5 ? '(' : ')'; continue; }
    let depth = 0;
    const len = 2 + Math.floor(rand() * 400);
    for (let k = 0; k < len && s.length < n; k++) {
      if (depth > 0 && (rand() < 0.5 || depth >= 40)) { s += ')'; depth--; }
      else { s += '('; depth++; }
    }
    while (depth > 0 && s.length < n) { s += ')'; depth--; }
  }
  return [s];
}
